import{_ as o,o as a,c as s,a2 as p}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Macro-Expressions.md","filePath":"manual-zh/Macro-Expressions.md","lastUpdated":1785684581000}'),t={name:"manual-zh/Macro-Expressions.md"};function c(r,e,d,n,i,_){return a(),s("div",null,[...e[0]||(e[0]=[p('<h4 id="_14-2-7-macro-expressions" tabindex="-1">14.2.7 Macro Expressions <a class="header-anchor" href="#_14-2-7-macro-expressions" aria-label="Permalink to &quot;14.2.7 Macro Expressions&quot;">​</a></h4><p>宏表达式用于条件展开和循环，这些将在后续章节中描述。宏表达式可以使用下列运算符，按运算符优先级从高到低列出：</p><p><code>()</code></p><p>括号覆盖默认的运算符优先级。</p><p><code>!EQ !NE !GT !LT !GE !LE = ~= &lt;&gt; &gt; &lt; &gt;= &lt;=</code></p><p>关系运算符比较其操作数并产生布尔结果，‘0’表示假，‘1’表示真。</p><p>这些运算符总是将其操作数作为字符串进行比较。当字符串是数字时这可能令人意外，因为例如 <code>1 &lt; 1.0</code> 和 <code>10 &lt; 2</code> 都求值为‘1’（真）。</p><p>比较区分大小写，因此 <code>a = A</code> 求值为‘0’（假）。</p><p><code>!NOT ~</code><code>!AND &amp;</code><code>!OR |</code></p><p>逻辑运算符将其操作数解释为布尔值，其中带引号或不带引号的‘0’为假，其他任何值为真，并产生布尔结果，‘0’表示假，‘1’表示真。</p><p>宏表达式不包含任何算术运算符。</p><p>表达式中的操作数可以是单个记号（包括宏参数名）或宏函数调用。无论哪种情况，表达式求值器都会对该操作数去引号，因此 <code>1 = &#39;1&#39;</code> 为真。</p>',12)])])}const x=o(t,[["render",c]]);export{m as __pageData,x as default};
